309.sql:
SELECT atom_id, (SELECT COUNT(DISTINCT bond_type) FROM bond WHERE molecule_id = 'TR346') AS bond_type_count
FROM atom
WHERE molecule_id = 'TR346';

303.sql:
SELECT 
    (SELECT COUNT(*) FROM bond WHERE molecule_id = 'TR006' AND bond_type = ' = ') AS double_bond_count,
    (SELECT label FROM molecule WHERE molecule_id = 'TR006') AS is_carcinogenic;

996.sql:
SELECT COUNT(*) / 11 AS annual_average
FROM races
WHERE date BETWEEN '2000-01-01' AND '2010-12-31';
